1	<script lang="ts">
2		/**
3		 * Import historical Expenses from a CSV / Excel file.
4		 *
5		 * Columns: Timestamp, Merchant, Amount, Category (Tag is ignored). Amount keeps
6		 * its sign (positive = expense, negative = refund), matching receipts. Each row
7		 * becomes an imageless receipt + a category link. The flow is two-step:
8		 * pick a file → review a preview (rows, duplicates, new categories) → confirm.
9		 *
10		 * All logic lives in ExpenseImportService + its pure helpers; this page only
11		 * drives the flow. Design: docs/plans/2026-07-09-spending-report-design.md
12		 */
13	
14		import { onMount } from 'svelte';
15		import { resolve } from '$app/paths';
16		import { supabase } from '$lib/supabaseClient';
17		import { getDefaultFamilyId } from '$lib/utils/familyUtils';
18		import {
19			ExpenseImportService,
20			type ExpenseImportPreview,
21			type ExpenseImportResult
22		} from '$lib/services/ExpenseImportService';
23		import { formatCurrency } from '$lib/utils/formatCurrency';
24		import Notification from '$lib/components/Notification.svelte';
25		import type { Session } from '@supabase/supabase-js';
26	
27		const service = new ExpenseImportService(supabase);
28	
29		let session: Session | null = $state(null);
30		let familyId: string | null = $state(null);
31		let error: string | null = $state(null);
32	
33		// Flow state: pick → preview → committing → done.
34		let busy = $state(false);
35		let preview = $state<ExpenseImportPreview | null>(null);
36		let result = $state<ExpenseImportResult | null>(null);
37	
38		const totalToImport = $derived(preview?.toInsert.length ?? 0);
39	
40		onMount(async () => {
41			const { data } = await supabase.auth.getSession();
42			session = data.session;
43			if (!session) return;
44			familyId = await getDefaultFamilyId();
45			if (!familyId) error = 'No family found. Please contact support.';
46		});
47	
48		async function onFileSelected(e: Event): Promise<void> {
49			const input = e.target as HTMLInputElement;
50			const file = input.files?.[0];
51			if (!file || !familyId) return;
52	
53			busy = true;
54			error = null;
55			preview = null;
56			result = null;
57			try {
58				preview = await service.buildPreview(familyId, file);
59			} catch (err) {
60				error = err instanceof Error ? err.message : 'Failed to read the file';
61			} finally {
62				busy = false;
63				input.value = ''; // allow re-selecting the same file
64			}
65		}
66	
67		async function confirmImport(): Promise<void> {
68			if (!familyId || !preview) return;
69			busy = true;
70			error = null;
71			try {
72				result = await service.commit(familyId, preview.toInsert);
73				preview = null;
74			} catch (err) {
75				error = err instanceof Error ? err.message : 'Failed to import expenses';
76			} finally {
77				busy = false;
78			}
79		}
80	
81		function cancelPreview(): void {
82			preview = null;
83		}
84	</script>
85	
86	<svelte:head>
87		<title>Import Expenses</title>
88	</svelte:head>
89	
90	<div class="mx-auto max-w-2xl">
91		<div class="mb-6">
92			<h1 class="mb-2 text-2xl font-bold">Import Expenses</h1>
93			<p class="text-gray-600">
94				Upload a historical expense file (CSV, XLS, or XLSX) with columns
95				<span class="font-medium">Timestamp, Merchant, Amount, Category</span>. Each row becomes an
96				expense — no receipt image needed. A negative amount is treated as a refund.
97			</p>
98		</div>
99	
100		{#if error}
101			<Notification type="error" message={error} onDismiss={() => (error = null)} />
102		{/if}
103	
104		{#if !session}
105			<p class="text-gray-600">Please log in to import expenses.</p>
106		{:else}
107			<!-- Step 1: pick a file (hidden while a preview is open or after a result) -->
108			{#if !preview && !result}
109				<div class="mb-6 rounded border bg-white p-4 shadow-sm">
110					<h2 class="mb-3 font-semibold">Choose a file</h2>
111					<label
112						class="inline-flex cursor-pointer items-center justify-center gap-2 rounded border bg-blue-600 px-4 py-2 text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
113					>
114						<input
115							type="file"
116							accept=".csv,.xls,.xlsx"
117							onchange={onFileSelected}
118							disabled={busy || !familyId}
119							class="hidden"
120						/>
121						{busy ? 'Reading…' : 'Select CSV / Excel File'}
122					</label>
123					<p class="mt-2 text-xs text-gray-500">
124						Nothing is saved until you review and confirm the next step. Re-importing the same file is
125						safe — rows already in your records are skipped.
126					</p>
127				</div>
128			{/if}
129	
130			<!-- Step 2: preview + confirm -->
131			{#if preview}
132				<div class="mb-6 rounded border bg-white p-4 shadow-sm">
133					<h2 class="mb-3 font-semibold">Review before importing</h2>
134	
135					<ul class="mb-4 space-y-1 text-sm">
136						<li>
137							<span class="font-semibold text-green-700">{totalToImport}</span>
138							{totalToImport === 1 ? 'expense' : 'expenses'} will be imported.
139						</li>
140						{#if preview.duplicatesSkipped > 0}
141							<li class="text-gray-600">
142								{preview.duplicatesSkipped}
143								{preview.duplicatesSkipped === 1 ? 'duplicate' : 'duplicates'} already in your records will
144								be skipped.
145							</li>
146						{/if}
147						{#if preview.parseErrors.length > 0}
148							<li class="text-amber-700">
149								{preview.parseErrors.length}
150								{preview.parseErrors.length === 1 ? 'row' : 'rows'} couldn't be read and will be skipped.
151							</li>
152						{/if}
153					</ul>
154	
155					{#if preview.newCategoryNames.length > 0}
156						<div class="mb-4 rounded border border-amber-200 bg-amber-50 p-3 text-sm text-amber-800">
157							<p class="font-medium">
158								{preview.newCategoryNames.length} new categor{preview.newCategoryNames.length === 1
159									? 'y'
160									: 'ies'} will be created:
161							</p>
162							<p class="mt-1">{preview.newCategoryNames.join(', ')}</p>
163							<p class="mt-2">
164								These start out <span class="font-medium">Uncategorized</span> in the Spending report.
165								File them under a Grouping in the
166								<a href={resolve('/spending/hierarchy')} class="underline">hierarchy editor</a> afterward.
167							</p>
168						</div>
169					{/if}
170	
171					{#if preview.parseErrors.length > 0}
172						<details class="mb-4 text-sm">
173							<summary class="cursor-pointer text-amber-700">Show rows that will be skipped</summary>
174							<ul
175								class="mt-2 max-h-40 overflow-y-auto rounded border border-amber-200 bg-amber-50 p-2"
176							>
177								{#each preview.parseErrors as msg (msg)}
178									<li class="text-amber-800">{msg}</li>
179								{/each}
180							</ul>
181						</details>
182					{/if}
183	
184					{#if totalToImport > 0}
185						<div class="max-h-64 overflow-y-auto rounded border">
186							<table class="w-full text-left text-sm">
187								<thead class="sticky top-0 bg-gray-50 text-xs text-gray-600">
188									<tr>
189										<th class="px-3 py-2">Date</th>
190										<th class="px-3 py-2">Merchant</th>
191										<th class="px-3 py-2 text-right">Amount</th>
192										<th class="px-3 py-2">Category</th>
193									</tr>
194								</thead>
195								<tbody>
196									{#each preview.toInsert as row, i (i)}
197										<tr class="border-t">
198											<td class="px-3 py-1.5 whitespace-nowrap">{row.transaction_date}</td>
199											<td class="px-3 py-1.5">{row.merchant_name}</td>
200											<td
201												class="px-3 py-1.5 text-right {row.total_amount < 0 ? 'text-green-600' : ''}"
202											>
203												{formatCurrency(row.total_amount)}
204											</td>
205											<td class="px-3 py-1.5 text-gray-600">
206												{row.categoryName ?? 'Uncategorized'}
207											</td>
208										</tr>
209									{/each}
210								</tbody>
211							</table>
212						</div>
213					{:else}
214						<p class="text-gray-600">Nothing new to import — every row is already in your records.</p>
215					{/if}
216	
217					<div class="mt-4 flex items-center gap-3">
218						<button
219							type="button"
220							onclick={confirmImport}
221							disabled={busy || totalToImport === 0}
222							class="rounded bg-blue-600 px-4 py-2 text-sm text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
223						>
224							{busy
225								? 'Importing…'
226								: `Import ${totalToImport} ${totalToImport === 1 ? 'expense' : 'expenses'}`}
227						</button>
228						<button
229							type="button"
230							onclick={cancelPreview}
231							disabled={busy}
232							class="rounded border border-gray-300 px-4 py-2 text-sm hover:bg-gray-100"
233						>
234							Cancel
235						</button>
236					</div>
237				</div>
238			{/if}
239	
240			<!-- Step 3: result -->
241			{#if result}
242				<div class="mb-6 rounded border bg-white p-4 shadow-sm">
243					<Notification
244						type="success"
245						message={`Imported ${result.imported} ${result.imported === 1 ? 'expense' : 'expenses'}${result.categoriesCreated > 0 ? `, created ${result.categoriesCreated} new categor${result.categoriesCreated === 1 ? 'y' : 'ies'}` : ''}.`}
246					/>
247					{#if result.categoriesCreated > 0}
248						<p class="mb-3 text-sm text-gray-600">
249							New categories are <span class="font-medium">Uncategorized</span> — file them in the
250							<a href={resolve('/spending/hierarchy')} class="underline">hierarchy editor</a>.
251						</p>
252					{/if}
253					<div class="flex items-center gap-3">
254						<a
255							href={resolve('/spending')}
256							class="rounded bg-blue-600 px-4 py-2 text-sm text-white hover:bg-blue-700"
257						>
258							View Spending report
259						</a>
260						<button
261							type="button"
262							onclick={() => (result = null)}
263							class="rounded border border-gray-300 px-4 py-2 text-sm hover:bg-gray-100"
264						>
265							Import another file
266						</button>
267					</div>
268				</div>
269			{/if}
270		{/if}
271	</div>
