2		import '../app.css';
3		import { supabase } from '$lib/supabaseClient';
4		import { onMount } from 'svelte';
5		import { writable } from 'svelte/store';
6		import { SvelteURLSearchParams } from 'svelte/reactivity';
7		import { page } from '$app/stores';
8		import { resolve } from '$app/paths';
9		import { APP_VERSION } from '$lib/version';
10		import type { Snippet } from 'svelte';
11	
12		let { children }: { children: Snippet } = $props();
13	
14		type Session = Awaited<ReturnType<typeof supabase.auth.getSession>>['data']['session'];
15		const session = writable<Session | null>(null);
16		let authChecked = $state(false);
17	
18		// #{#ath1a} Public routes that do not require authentication
19		const publicRoutes = ['/', '/login', '/forgot-password', '/reset-password'];
20	
21		let isPublicRoute = $derived(publicRoutes.includes($page.url.pathname));
22	
23		onMount(() => {
24			// Subscribe synchronously so onMount can return a synchronous cleanup
25			// (an async onMount callback can't return a teardown function).
26			const { data: sub } = supabase.auth.onAuthStateChange((_e, s) => session.set(s));
27	
28			void (async () => {
29				const { data } = await supabase.auth.getSession();
30				session.set(data.session);
31				authChecked = true;
32			})();
33	
34			return () => {
35				sub.subscription.unsubscribe();
36			};
37		});
38	
39		async function logout() {
40			await supabase.auth.signOut();
41			window.location.href = '/login';
42		}
43	
44		// #{#sdf3a} Preserve date filter query parameters in navigation.
45		// `resolve()` only accepts a single concrete route literal, so each nav link
46		// branches `resolve(`/route?${filterQuery}`)` vs `resolve('/route')` (see the
47		// same pattern in expenses/+page.svelte). This derived is just the query body
48		// (no leading `?`), shared by every link.
49		let filterQuery = $derived.by(() => {
50			const params = $page.url.searchParams;
51			const dateFrom = params.get('dateFrom');
52			const dateTo = params.get('dateTo');
53	
54			const newParams = new SvelteURLSearchParams();
55			if (dateFrom) newParams.set('dateFrom', dateFrom);
56			if (dateTo) newParams.set('dateTo', dateTo);
57	
58			return newParams.toString();
59		});
60	</script>
