1	<script lang="ts">
2		import { supabase } from '$lib/supabaseClient';
3		import { onMount } from 'svelte';
4		import { resolve } from '$app/paths';
5		import {
6			isValidEmail,
7			isDuplicateEmail,
8			firstAvailableSlot,
9			slotIndexOfEmail,
10			slotColumn
11		} from '$lib/utils/profileEmails';
12	
13		type Session = Awaited<ReturnType<typeof supabase.auth.getSession>>['data']['session'];
14		type Profile = {
15			id: string;
16			user_id: string;
17			email_1: string | null;
18			email_2: string | null;
19			email_3: string | null;
20			email_4: string | null;
21			email_5: string | null;
22			created_at: string;
23			updated_at: string;
24		};
25	
26		let session = $state<Session | null>(null);
27		let profile = $state<Profile | null>(null);
28		let loading = $state(true);
29		let error = $state('');
30	
31		// Email management state
32		let isAddingEmail = $state(false);
33		let newEmailInput = $state('');
34		let editingIndex: number | null = $state(null);
35		let editEmailInput = $state('');
36		let deletingEmail: { index: number; email: string } | null = $state(null);
37		let savingEmail = $state(false);
38		let deletingInProgress = $state(false);
39	
40		onMount(() => {
41			// Subscribe to auth state changes synchronously so onMount can return a
42			// synchronous cleanup (an async onMount callback can't return a teardown).
43			const { data: subscription } = supabase.auth.onAuthStateChange(async (_event, newSession) => {
44				session = newSession;
45				if (newSession) {
46					await loadProfile();
47				} else {
48					profile = null;
49				}
50			});
51	
52			// Initial session load (#{#upp1a})
53			void (async () => {
54				const { data } = await supabase.auth.getSession();
55				session = data.session;
56				if (session) {
57					await loadProfile();
58				}
59				loading = false;
60			})();
61	
62			return () => {
63				subscription.subscription.unsubscribe();
64			};
65		});
66	
67		async function loadProfile() {
68			if (!session?.user?.id) return;
69	
70			const { data, error: err } = await supabase
71				.from('profiles')
72				.select('*')
73				.eq('user_id', session.user.id)
74				.single();
75	
76			if (err) {
77				// If no profile exists yet, that's okay - user can still add emails
78				if (err.code !== 'PGRST116') {
79					console.error('Error loading profile:', err);
80					error = 'Failed to load profile data';
81				}
82			} else {
83				profile = data;
84			}
85		}
86	
87		// Extract user info from session (#{#upp2b})
88		let userEmail = $derived(session?.user?.email || '');
89		let userId = $derived(session?.user?.id || '');
90		let createdAt = $derived(
91			session?.user?.created_at ? new Date(session.user.created_at).toLocaleDateString() : ''
92		);
93	
94		// Extract additional emails from profile (#{#upp4a})
95		let additionalEmails = $derived(
96			profile
97				? ([
98						profile.email_1,
99						profile.email_2,
100						profile.email_3,
101						profile.email_4,
102						profile.email_5
103					].filter((email) => email !== null && email !== '') as string[])
104				: []
105		);
106	
107		// Add email functionality (#{#upp4b})
108		function startAddingEmail() {
109			isAddingEmail = true;
110			newEmailInput = '';
111			error = '';
112		}
113	
114		function cancelAddingEmail() {
115			isAddingEmail = false;
116			newEmailInput = '';
117			error = '';
118		}
119	
120		async function saveNewEmail() {
121			if (!session?.user?.id) return;
122	
123			// Validate email format (#{#upp4b})
124			if (!isValidEmail(newEmailInput)) {
125				error = 'Please enter a valid email address';
126				return;
127			}
128	
129			// Check for duplicates (case-insensitive)
130			const existingEmails = [userEmail, ...additionalEmails];
131	
132			if (isDuplicateEmail(newEmailInput, existingEmails)) {
133				error = 'This email address is already in your profile';
134				return;
135			}
136	
137			savingEmail = true;
138			error = '';
139	
140			try {
141				// Find first available email slot
142				const usedSlots = profile
143					? [profile.email_1, profile.email_2, profile.email_3, profile.email_4, profile.email_5]
144					: [null, null, null, null, null];
145	
146				const firstAvailableIndex = firstAvailableSlot(usedSlots);
147				const columnToUpdate = firstAvailableIndex === null ? null : slotColumn(firstAvailableIndex);
148	
149				if (columnToUpdate === null) {
150					error = 'All email slots are full';
151					savingEmail = false;
152					return;
153				}
154	
155				// Create or update profile record
156				if (!profile) {
157					// Create new profile record
158					const { error: insertErr } = await supabase.from('profiles').insert({
159						user_id: session.user.id,
160						[columnToUpdate]: newEmailInput.trim()
161					});
162	
163					if (insertErr) {
164						console.error('Error creating profile:', insertErr);
165						error = 'Failed to add email address';
166					} else {
167						await loadProfile();
168						isAddingEmail = false;
169						newEmailInput = '';
170					}
